return {
  [ [[v5748eaic9vhk]] ] = { t = [[远古血脉与永远可用种族]], q = [=[某些角色选项，例如《[[进阶玩家指南]]》中的[[远古血脉]]专长，允许角色视为另一个种族的成员。我可以用这些选项视为任何种族的成员，还是只能视为《探索者协会组织游戏指南》中“永远可用”列表上的种族？]=], a = [[通常你只能用这些选项来视为“永远可用”列表中某个种族的成员。不过，如果你有一项允许你扮演另一种族成员的福利，你可以把这项福利用在某个角色身上，从而解锁带上该种族特性的能力，例如通过远古血脉专长之类的选项。举例来说，你可以把鼠人福利用在一名人类角色上，让该角色能通过远古血脉专长选择鼠人专属的种族选项，只要这些选项不依赖鼠人特有的身体特征。更多信息请参见关于额外资源的这条 FAQ。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vhk]], cat = [[PFS]], ai = true, pages = { [[远古血脉]], [[PFS：创建角色]] } },
  [ [[v5748eaic9vha]] ] = { t = [[游侠的动物伙伴]], q = [[游侠可以选择哪些动物伙伴？]], a = [=[作为游侠，如果你为自己的猎手羁绊选择了[[动物伙伴]]，就只能从《核心规则书》第66页列出的动物中挑选。除非来自其他合法资源的授予，探索者协会组织游戏中游侠没有其他可选的动物伙伴。]=], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vha]], cat = [[PFS]], ai = true, pages = { [[游侠]] } },
  [ [[v5748eaic9vh1]] ] = { t = [[替换死去的伙伴]], q = [[如何处理死去的魔宠、动物伙伴或其他伙伴生物的替换？]], a = [=[如果你在冒险过程中失去了伙伴，请在记录单上记下这一损失。要替换伙伴，需支付所有所需的费用。你的新伙伴会在下一场冒险开始时就绪。新召来的动物伙伴在开局时已掌握的技巧数量，等于按德鲁伊等级获得的额外技巧数。所有其他技巧都需要照上一条 FAQ 的规定，用[[驯养动物]]来训练这只新的动物伙伴。]=], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vh1]], cat = [[PFS]], ai = true, pages = { [[休整期活动]] } },
  [ [[v5748eaic9vh8]] ] = { t = [[重训伙伴生物]], q = [[我能重训动物伙伴、坐骑、魔宠、幻灵或其他伙伴生物吗？]], a = [=[你可以按《[[极限战役]]》的[[重训]]规则重训伙伴生物的专长和技能点，所需的金币和声望点数与你为自己的角色重训这些能力时相同。你可以像教导生物一项新技巧那样，用[[驯养动物]]重训动物伙伴或坐骑的技巧。]=], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vh8]], cat = [[PFS]], ai = true, pages = { [[重训]], [[休整期活动]] } },
  [ [[v5748eaic9vhy]] ] = { t = [[储法物品跨冒险保留法术]], q = [=[储法物品（例如[[法术反制戒指]]或[[储法(武器附魔)|储法武器]]）能否把存入的法术从一场冒险带到另一场冒险？]=], a = [[可以。能施法的 PC 可以向自己拥有的储法物品里施放法术；PC 也可以付钱请 NPC 施法者往自己的储法物品里施放法术。如果他在冒险结束前没有用掉这个法术，它会保留到下一场冒险。GM 应当在这场冒险的记录单上注明该储法物品里有一个法术；PC 施放该法术时，把记录单上的这条注记划掉。

PC 之间可以临时为彼此的储法物品充入法术，但这类法术不会带到下一场冒险。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vhy]], cat = [[PFS]], ai = true, pages = { [[储法戒指]], [[储法(武器附魔)]], [[PFS：特殊规则]] } },
  [ [[v5748eaic9whf]] ] = { t = [[鞍座与异种鞍座]], q = [[在组织游戏中，鞍座和异种鞍座有什么区别？魔法异种鞍座要额外付费吗？]], a = [[在组织游戏中，《Pathfinder 角色扮演游戏核心规则书》装备一节列出的生物（狗、骡、驴、矮种马和马）可以使用普通鞍座，其他所有生物都使用异种鞍座。魔法鞍座无论是普通鞍座还是异种鞍座，价格都相同。]], book = [[探索者协会组织游戏指南6.0]], date = [[2018/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9whf]], cat = [[PFS]], ai = true, pages = { [[鞍座]] } },
  [ [[v5748eaic9vib]] ] = { t = [[卷轴与奥术失败率]], q = [[按《探索者协会组织游戏指南》，奥术、神术和异能卷轴之间没有区别。那么使用卷轴时有奥术失败率吗？]], a = [[没有。在组织游戏中，卷轴从不带来奥术失败率。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vib]], cat = [[PFS]], ai = true, pages = { [[PFS：特殊规则]], [[魔法物品/卷轴]] } },
  [ [[v5748eaic9vi0]] ] = { t = [[使用魔法装置施放卷轴所需的属性]], q = [=[通过[[使用魔法装置]]技能施放卷轴上的法术，需要“相应属性值至少为（10+法术环位）”。我该如何确定相应的属性？]=], a = [=[《组织游戏指南》说明了给卷轴定价时如何确定使用哪个职业的法术列表。在组织游戏战役中，我们假定是该职业的角色制作了这张卷轴。卷轴对应的属性就是该职业典型的施法属性值。如果按指南的规则不止一个职业能制作这张卷轴，你可以自行选择职业。例如，[[忍受环境]]在牧师、德鲁伊和术士／法师的法术列表上都是1环法术。你可以选择购买由牧师或德鲁伊制作的卷轴，使用感知；由术士制作的卷轴，使用魅力；或由法师制作的卷轴，使用智力。]=], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vi0]], cat = [[PFS]], ai = true, pages = { [[PFS：特殊规则]], [[魔法物品/卷轴]] } },
  [ [[v5748eaic9vi5]] ] = { t = [[多法术卷轴]], q = [[我能购买写有多个法术的卷轴吗？]], a = [=[可以。你可以购买一张最多写有6个法术的卷轴。卷轴每多写一个法术就要长一尺，超过这个长度的卷轴会变得笨重。只要卷轴上全是同一个法术的多份副本，你就可以用声望点数购买写有多个法术的卷轴。例如，你可以用2点声望点数购买一张写有5份[[灼热射线]]的卷轴，而不必花750 gp购买。]=], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vi5]], cat = [[PFS]], ai = true, pages = { [[PFS：特殊规则]], [[魔法物品/卷轴]] } },
  [ [[v5748eaic9vi6]] ] = { t = [[出售法术书]], q = [[我能把法术书按半价卖回去吗？]], a = [[你可以按你抄录并付费的法术总价值的一半出售法术书，不计入你通过福利、升级或任何其他免费途径获得的法术。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vi6]], cat = [[PFS]], ai = true, pages = { [[魔法]] } },
  [ [[v5748eaic9vig]] ] = { t = [[施法服务失败]], q = [[当我购买施法服务来移除某个状态，而法术未能移除该状态时，我能否免费获得额外的施法，直到成功为止？]], a = [[不能。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vig]], cat = [[PFS]], ai = true, pages = { [[施法服务]], [[PFS：特殊规则]] } },
  [ [[v5748eaic9vih]] ] = { t = [[高于最低施法者等级的施法服务]], q = [[我能购买高于最低施法者等级的施法服务吗？]], a = [[如果该法术出现在《探索者协会组织游戏指南》的声望回报列表上，你可以购买高于最低施法者等级的施法服务。其他所有法术的施法服务都只能按最低施法者等级购买。用声望点数购买的法术始终是最低施法者等级。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vih]], cat = [[PFS]], ai = true, pages = { [[施法服务]], [[PFS：特殊规则]] } },
  [ [[v5748eaic9vi4]] ] = { t = [[法杖充能跨冒险保留]], q = [[法杖之类的物品，其充能能否在冒险之间保留？]], a = [[可以。注意，如果你能用自己的施法为法杖充能，那么两场冒险之间间隔的天数是不确定的，这通常意味着你每场冒险开始时法杖都是充满的。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vi4]], cat = [[PFS]], ai = true, pages = { [[魔法物品/法杖]], [[PFS：特殊规则]] } },
  [ [[v5748eaic9vif]] ] = { t = [[毒药与武器涂层跨冒险保留]], q = [[毒药和武器涂层的效果能否在冒险之间保留？]], a = [[可以。这些物品会一直保留，直到用掉。注意，该物品已经在这场冒险的记录单上记为施用过了。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vif]], cat = [[PFS]], ai = true, pages = { [[武器涂层（精金）]], [[武器涂层（鬼灵盐）]], [[特殊能力]] } },
  [ [[v5748eaic9vi7]] ] = { t = [[武器链与装填]], q = [[武器链会妨碍装填吗？]], a = [[不会。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vi7]], cat = [[PFS]], ai = true, pages = { [[武器链]] } },
  [ [[v5748eaic9vid]] ] = { t = [[升级奥术联结物品]], q = [[我能升级奥术联结物品吗？]], a = [=[拥有奥术联结职业能力的角色，可以与自己拥有的任何物品缔结联结——魔法物品或普通物品皆可——只要该物品属于奥术联结能力允许的类别（与新物品缔结联结的费用仍然适用）。如果施法者之后想升级现有的联结物品，他可以支付物品属性栏里所列最终物品的成本（cost，而非价格）。

对于可以逐步强化的物品（例如武器或[[防护戒指]]），施法者必须满足物品制作规则中列出的该物品的所有先决条件。例如，施法者可以花1,000 gp（而不是正常的2,000 gp）把非魔法的联结匕首附魔成+1匕首，但他必须至少是5级（[[制造魔法武器和防具]]专长的先决条件）。要把它进一步升级为+2匕首，施法者的施法者等级必须达到6或更高（物品强化加值的三倍）。

被强化的联结物品仍必须遵守所有关于获取和升级魔法物品的战役规则。要用物品最终的总价格（而不是成本）在名誉表上查对，来判断施法者能否对联结物品进行这种强化。]=], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vid]], cat = [[PFS]], ai = true, pages = { [[法师]] } },
  [ [[v5748eaic9vhz]] ] = { t = [[奥术联结与记录单上的特殊物品]], q = [=[我能与记录单上列出的特殊物品（例如[[智能物品]]）缔结奥术联结吗？]=], a = [[拥有奥术联结职业能力的角色可以与智能物品缔结联结。她无法制作智能物品，所以必须支付该物品的全额购买价格。

记录单上的某些物品是以折扣价提供的。施法者既可以按所列折扣价购买这些物品并与之缔结联结，也可以按物品的标准制作成本（不适用折扣）自行制作。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vhz]], cat = [[PFS]], ai = true, pages = { [[法师]] } },
  [ [[v5748eaic9vhx]] ] = { t = [[法术知识戒指与神术法术]], q = [[法术知识戒指能否让使用者获得神术法术，例如女巫庇护主列表上的法术？]], a = [[不能。虽然在组织游戏中奥术、神术和异能法术通常没有区别，但法术知识戒指只授予出现在奥术施法者法术列表上的法术。确定法术环位时，按《组织游戏指南》中为购买魔杖、卷轴和药水而确定法术环位的规则，忽略神术和异能施法者。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vhx]], cat = [[PFS]], ai = true, pages = { [[法术知识戒指]] } },
  [ [[v5748eaic9tb7]] ] = { t = [[掉链盗贼的巧技训练]], q = [=[[[掉链盗贼]]的巧技训练：当我用敏捷取代力量时，单手武器会怎样？副手武器呢？]=], a = [=[使用双手武器时，你在伤害检定上加上1.5倍的敏捷加值；使用副手武器时，你在伤害检定上加上半数敏捷加值。如能力描述所述，若有某个效果会妨碍你把力量调整值加到伤害检定上，你也不会加上敏捷调整值。但是，任何会提高你力量加值在伤害检定上的倍数的其他效果（例如[[双手战士]]变体职业的过肩斩）都不会影响你的敏捷加值在伤害检定上的倍数。]=], book = [[冒险之路95：烈火铁砧]], date = [[2015/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1h3#v5748eaic9tb7]], cat = [[FAQ]], ai = true, pages = { [[掉链盗贼]] } },
}